-- ============================================================================
-- B5 FOLLOW-ON W2 (publish inputs in prompts and lessons): separation.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 1,
-- route (a), and the spec docs/graded-field-audit/w2/separation.json (the
-- inputs, where each came from, and the key each reproduces through the
-- vendored engines). Owner approved D1 to D7 as recommended, 2026-09-21.
--
-- ADVANCED
--   Prompt only, no field moves. The ADANGA item positions existed only in
--   capstone-only code (separationLab.js ADANGA_ITEMS, guarded from panels), so
--   neither layout ranking could be worked (B5 finding 1). The prompt now states
--   each placed item as north and east offsets from the datum, the two scale
--   factors the Mapper uses and the haversine radius, so both shortfalls are a
--   hand calculation (intermediate m05 l02). It also asks for the fraction to
--   six decimals, which is what its tol of 1e-6 needs; "four decimals or better"
--   failed a learner who followed it. The Facility Layout Mapper print
--   (SpacingPanel.jsx:179) is W3.
--   PROMPT was: with a portable flare that was never placed and a second slop
--   tank carrying no coordinates.
--   PROMPT now: with a portable flare that was never placed and a second slop
--   tank carrying no coordinates. THE YARD, each item given as its name, its
--   type and its position in metres north and east of the datum at 4.9021 N,
--   6.8714 E: Wellhead A, wellhead, 0 N 0 E; Wellhead B, wellhead, 4 N 0 E;
--   Manifold, manifold, 26 N 14 E; Test separator, separator, 48 N 30 E;
--   Isolation valve, valve, 50 N 32 E; Custody flow meter, flowmeter, 70 N 44 E;
--   Slop tank, tank, 84 N 55 E; Yard flare, flare, 215 N 150 E; Yard control
--   room, control, 245 N 185 E. Turn an offset into latitude and longitude as
--   the Mapper does, at 110574 m per degree of latitude and 111320 m times the
--   cosine of the datum latitude per degree of longitude, and measure every
--   distance centre to centre by the haversine formula on a sphere of radius
--   6371008.8 m. Read the figures in the Separator Studio and the Facility
--   Layout Mapper with their Full precision switch on (at the top of the page):
--   they print them to the precision this capstone grades, with no digit
--   grouping.
--   PROMPT was: Lengths in ft, times in s, distances in m and the fraction as a
--   fraction, to four decimals or better.
--   PROMPT now: Lengths in ft, times in s and distances in m to four decimals or
--   better, and the fraction as a fraction to six decimals.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected value and
-- tolerance), title, dataset, status and the row. The guard requires `fields`
-- to equal its live value exactly, before and after, so no answer grades
-- differently, nobody is re-scored and no attempts guard is needed.
--
-- GUARDS. Each row must hold EITHER its published prompt (by md5) with its
-- live fields (exact jsonb), as production holds it after W1 (it is
-- rewritten), OR its W2 prompt with the same fields (left alone). Anything
-- else raises and the whole file rolls back. A file that will write first
-- checks the W1 post-state and refuses without it. Generated by
-- docs/graded-field-audit/w2_capstones.py. SAFE TO RE-RUN: a second run
-- writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_s0       text;
begin
  -- separation / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'separation' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w2 separation refused: separation/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '481720150f12adca7c39372b57c3b56a' and fields = '[{"key": "ejulebe3_interface_height_ft", "tol": 0.00005, "unit": "ft", "label": "Oil-water interface at its exact height", "expected": 3.5272802173244173}, {"key": "ejulebe3_water_drop_fall_s", "tol": 0.001, "unit": "s", "label": "Time for the specified water droplet to cross the oil layer", "expected": 388.0364348552262}, {"key": "ejulebe3_oil_drop_rise_s", "tol": 0.001, "unit": "s", "label": "Time for the specified oil droplet to rise through the water layer", "expected": 340.8355864500273}, {"key": "ejulebe4_preferred_height_ft", "tol": 0.0001, "unit": "ft", "label": "Height of the preferred vessel in the family", "expected": 9.094348494300087}, {"key": "adanga_worst_absolute_shortfall_m", "tol": 0.0001, "unit": "m", "label": "Worst absolute shortfall on the layout", "expected": 53.82226310078884}, {"key": "adanga_worst_relative_fraction", "tol": 0.000001, "unit": "fraction", "label": "Worst relative shortfall on the layout, as a fraction of the requirement", "expected": 0.6200257720948125}]'::jsonb then 'old'
              when md5(prompt) = 'f2c5e0ccc1946df9ca9c19b60154e855' and fields = '[{"key": "ejulebe3_interface_height_ft", "tol": 0.00005, "unit": "ft", "label": "Oil-water interface at its exact height", "expected": 3.5272802173244173}, {"key": "ejulebe3_water_drop_fall_s", "tol": 0.001, "unit": "s", "label": "Time for the specified water droplet to cross the oil layer", "expected": 388.0364348552262}, {"key": "ejulebe3_oil_drop_rise_s", "tol": 0.001, "unit": "s", "label": "Time for the specified oil droplet to rise through the water layer", "expected": 340.8355864500273}, {"key": "ejulebe4_preferred_height_ft", "tol": 0.0001, "unit": "ft", "label": "Height of the preferred vessel in the family", "expected": 9.094348494300087}, {"key": "adanga_worst_absolute_shortfall_m", "tol": 0.0001, "unit": "m", "label": "Worst absolute shortfall on the layout", "expected": 53.82226310078884}, {"key": "adanga_worst_relative_fraction", "tol": 0.000001, "unit": "fraction", "label": "Worst relative shortfall on the layout, as a fraction of the requirement", "expected": 0.6200257720948125}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'separation' and tier = 'advanced' and active;
  if v_s0 = 'other' then
    raise exception 'w2 separation refused: separation/advanced matches neither its published form (prompt md5 481720150f12adca7c39372b57c3b56a) nor its W2 form (prompt md5 f2c5e0ccc1946df9ca9c19b60154e855), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W2 form
  if v_s0 = 'new' then
    raise notice 'w2 separation: 0 of 1 row(s) written, all already applied';
    return;
  end if;

  -- W1 (20261024a/b) must be applied first: production holds it, and the W2
  -- apply script checks all 34 files; this reads two of its rows
  if exists (select 1 from public.academy_capstones where app_slug = 'integrity' and tier = 'beginner' and active and md5(prompt) <> '0e0ac66d6b97e9f7f66b5055e1fddf7d')
     or exists (select 1 from public.academy_capstones where app_slug = 'welldata' and tier = 'beginner' and active and md5(prompt) <> 'f362ed27e7d8766e7e51dcf1ca0e5e6e') then
    raise exception 'w2 separation refused: W1 (20261024*) is not applied on this database; apply it first (/root/w1-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'EJULEBE-3, the three-phase separator: gas 21 MMscfd at 290 psig and 124 degF with a gas gravity of 0.73; oil 9600 bopd at a specific gravity of 0.8762 and a viscosity of 6.5 cP; water 7200 bpd at a specific gravity of 1.07 and a viscosity of 0.75 cP; oil retention 7 minutes and water retention 9 minutes; a water droplet specification of 350 micron and an oil droplet specification of 150 micron; a vendor K of 0.37; a diameter of 11 ft; and a liquid level at 0.55 of the diameter. EJULEBE-4, the vertical scrubber downstream of the compressor: gas 70 MMscfd at 620 psig and 96 degF with a gas gravity of 0.69; oil 1900 bopd at 30 degrees API; water 350 bpd at a specific gravity of 1.05; retention 3 minutes; an allowance of 7 ft; a vendor K of 0.31; offered at 3, 3.5, 4, 4.5, 5 and 6 ft against an L/D band of 2 to 4. The ADANGA manifold yard, judged in the Facility Layout Mapper against the site''s own stated setbacks: the yard flare at 100 m to 6.31 kW/m2 and the slop tank pool fire at 47 m to 4.73 kW/m2, with a portable flare that was never placed and a second slop tank carrying no coordinates. THE YARD, each item given as its name, its type and its position in metres north and east of the datum at 4.9021 N, 6.8714 E: Wellhead A, wellhead, 0 N 0 E; Wellhead B, wellhead, 4 N 0 E; Manifold, manifold, 26 N 14 E; Test separator, separator, 48 N 30 E; Isolation valve, valve, 50 N 32 E; Custody flow meter, flowmeter, 70 N 44 E; Slop tank, tank, 84 N 55 E; Yard flare, flare, 215 N 150 E; Yard control room, control, 245 N 185 E. Turn an offset into latitude and longitude as the Mapper does, at 110574 m per degree of latitude and 111320 m times the cosine of the datum latitude per degree of longitude, and measure every distance centre to centre by the haversine formula on a sphere of radius 6371008.8 m. Read the figures in the Separator Studio and the Facility Layout Mapper with their Full precision switch on (at the top of the page): they print them to the precision this capstone grades, with no digit grouping. Report six values from the three-phase split, the two droplet crossings, the preferred vessel of the family and the two layout rankings. Lengths in ft, times in s and distances in m to four decimals or better, and the fraction as a fraction to six decimals.'
     where app_slug = 'separation' and tier = 'advanced' and active and md5(prompt) = '481720150f12adca7c39372b57c3b56a';
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w2 separation refused: separation/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'f2c5e0ccc1946df9ca9c19b60154e855' and fields = '[{"key": "ejulebe3_interface_height_ft", "tol": 0.00005, "unit": "ft", "label": "Oil-water interface at its exact height", "expected": 3.5272802173244173}, {"key": "ejulebe3_water_drop_fall_s", "tol": 0.001, "unit": "s", "label": "Time for the specified water droplet to cross the oil layer", "expected": 388.0364348552262}, {"key": "ejulebe3_oil_drop_rise_s", "tol": 0.001, "unit": "s", "label": "Time for the specified oil droplet to rise through the water layer", "expected": 340.8355864500273}, {"key": "ejulebe4_preferred_height_ft", "tol": 0.0001, "unit": "ft", "label": "Height of the preferred vessel in the family", "expected": 9.094348494300087}, {"key": "adanga_worst_absolute_shortfall_m", "tol": 0.0001, "unit": "m", "label": "Worst absolute shortfall on the layout", "expected": 53.82226310078884}, {"key": "adanga_worst_relative_fraction", "tol": 0.000001, "unit": "fraction", "label": "Worst relative shortfall on the layout, as a fraction of the requirement", "expected": 0.6200257720948125}]'::jsonb) from public.academy_capstones where app_slug = 'separation' and tier = 'advanced' and active) is not true then
    raise exception 'w2 separation refused: separation/advanced does not read back as its W2 form';
  end if;

  raise notice 'w2 separation: % of 1 row(s) written, % already applied', v_written, 1 - v_written;
end $$;
